  if (lang === "es") {
    if (!revenue || Number.isNaN(revenue) || revenue <= 0) return "Ingresa un ingreso válido mayor a 0.";
    if (cogs === undefined || Number.isNaN(cogs) || cogs < 0) return "Ingresa un costo de bienes vendidos válido (0 o más).";
    if (cogs > revenue) return "El costo de bienes vendidos no puede ser mayor que los ingresos.";
    return null;
  }
  if (!revenue || Number.isNaN(revenue) || revenue <= 0) {
    return "Please enter a valid revenue greater than 0.";
  }
  if (cogs === undefined || Number.isNaN(cogs) || cogs < 0) {
    return "Please enter a valid cost of goods sold (0 or more).";
  }
  if (cogs > revenue) {
    return "Cost of goods sold cannot be greater than revenue.";
  }

  return null;
}

